const crypto = require('crypto');
const sign = (secret, timestamp, body) =>
  'v1=' + crypto.createHmac('sha256', secret).update(timestamp + '.' + body).digest('hex');
const signedRequest = (path, bodyObject) => {
  const secret = $env.LENDLOOP_INBOUND_SECRET;
  if (!secret) throw new Error('LENDLOOP_INBOUND_SECRET is not set');
  const base = String($env.LENDLOOP_CONVEX_SITE_URL || 'http://convex-backend:3211').replace(/\/+$/, '');
  const timestamp = String(Math.floor(Date.now() / 1000));
  const body = JSON.stringify(bodyObject);
  return {
    url: base + path,
    body,
    headers: {
      'Content-Type': 'application/json',
      'X-LendLoop-Timestamp': timestamp,
      'X-LendLoop-Signature': sign(secret, timestamp, body),
      'X-LendLoop-Event-Id': bodyObject.idempotencyKey || ''
    }
  };
};
const inc = $('Evaluate incident').first().json;
const payload = { idempotencyKey: 'health-alert:' + inc.incidentKey, incidentKey: inc.incidentKey, dead: inc.dead, stuckPending: inc.stuckPending };
if (inc.oldestStuckAt != null) payload.oldestStuckAt = inc.oldestStuckAt;
return { json: signedRequest('/n8n/health-alert-sent', payload) };

const key = $('Evaluate incident').first().json.incidentKey;
const store = $getWorkflowStaticData('global');
const seen = Array.isArray(store.alertedIncidentKeys) ? store.alertedIncidentKeys : [];
if (!seen.includes(key)) seen.push(key);
// bounded so the static data cannot grow forever
store.alertedIncidentKeys = seen.slice(-100);
return [{ json: { remembered: key, total: store.alertedIncidentKeys.length } }];

const err = $json.error;
const message = String((typeof err === 'string' ? err : err && err.message) || 'alert email or write-back failed').slice(0, 200);
throw new Error('delivery health alert failed: ' + message);
